// Eagle canvas engine copied from cia_first_international_school_it_help_desk_live_code_drop_eagle_ui.html.
    (function() {
      // 1. Decode the 160x152 cleaned Eagle cyan intensity field (0..255)
      const GRID_W = 160;
      const GRID_H = 152;
      const EAGLE_B64 = "";
      const rawBin = atob(EAGLE_B64);
      const eagleData = new Uint8Array(rawBin.length);
      for (let i = 0; i < rawBin.length; i++) {
        eagleData[i] = rawBin.charCodeAt(i);
      }

      // Bilinear sampler for smooth eagle intensity at normalized coordinates (nx, ny) in [0, 1]
      function sampleEagle(nx, ny) {
        if (nx < 0 || nx > 1 || ny < 0 || ny > 1) return 0;
        const gx = nx * (GRID_W - 1);
        const gy = ny * (GRID_H - 1);
        const x0 = gx | 0;
        const y0 = gy | 0;
        const x1 = x0 < GRID_W - 1 ? x0 + 1 : x0;
        const y1 = y0 < GRID_H - 1 ? y0 + 1 : y0;
        const fx = gx - x0;
        const fy = gy - y0;
        const row0 = y0 * GRID_W;
        const row1 = y1 * GRID_W;
        const v00 = eagleData[row0 + x0];
        const v10 = eagleData[row0 + x1];
        const v01 = eagleData[row1 + x0];
        const v11 = eagleData[row1 + x1];
        const top = v00 + (v10 - v00) * fx;
        const bot = v01 + (v11 - v01) * fx;
        return (top + (bot - top) * fy) / 255.0;
      }

      // Compute local horizontal/vertical contrast (feather & beak edge sharpness)
      function sampleEagleEdge(nx, ny) {
        const epsX = 1.0 / GRID_W;
        const epsY = 1.0 / GRID_H;
        const c = sampleEagle(nx, ny);
        const l = sampleEagle(nx - epsX, ny);
        const r = sampleEagle(nx + epsX, ny);
        const u = sampleEagle(nx, ny - epsY);
        const d = sampleEagle(nx, ny + epsY);
        return Math.min(1.0, (Math.abs(r - l) + Math.abs(d - u)) * 2.2 + Math.max(0, c - (l + r + u + d) * 0.25) * 3.0);
      }

      const canvas = document.getElementById('codeDropEagleCanvas');
      const ctx = canvas.getContext('2d', { alpha: false });

      // Offscreen volumetric scanline canvas for hybrid mode
      const offCanvas = document.createElement('canvas');
      const offCtx = offCanvas.getContext('2d');
      const VOL_W = 200;
      const VOL_H = 190;
      offCanvas.width = VOL_W;
      offCanvas.height = VOL_H;
      const volImgData = offCtx.createImageData(VOL_W, VOL_H);
      const volPixels = volImgData.data;

      // Engine state
      let renderMode = 'hybrid'; // 'hybrid' | 'pure'
      let width = 600;
      let height = 600;
      let dpr = 1;

      // Interactive pointer state, shockwaves & LIVE EAGLE ACTIVITY STATE
      const pointer = { x: 0.5, y: 0.4, active: false, vx: 0, vy: 0 };
      const ripples = []; // { nx, ny, radius, maxRadius, strength }
      const featherSparks = []; // Floating binary feather particles emitted during eagle activity

      // Autonomous + Reactive Eagle Pose & Activity Controller
      const eagle = {
        yaw: 0,          // -1 (left) to +1 (right) 2.5D head turn
        targetYaw: 0,
        pitch: 0,        // -1 (up) to +1 (down) head nod
        targetPitch: 0,
        roll: 0,         // head tilt in radians
        targetRoll: 0,
        blink: 0,        // 0 = open, 1 = closed eyelid
        blinkPhase: 0,   // timer for active blink
        nextBlinkIn: 2.2,
        screech: 0,      // 0 = closed beak, 1 = wide open cyber screech
        screechTimer: 0,
        ruffle: 0,       // feather ruffle intensity
        scanBeamY: -1,   // holographic scan beam position (-1 = inactive)
        modeName: 'PATROL & SCANNING',
        nextActionIn: 2.8,
        watchingForm: false
      };

      const activityBadgeEl = document.getElementById('eagleActivityBadge');
      function setActivityLabel(text) {
        eagle.modeName = text;
        if (activityBadgeEl) activityBadgeEl.textContent = 'EAGLE: ' + text;
      }

      function triggerRipple(nx, ny, strength = 1.0) {
        ripples.push({ nx, ny, radius: 0.01, maxRadius: 0.68, strength });
        if (ripples.length > 6) ripples.shift();
      }

      function spawnFeatherBurst(count, centerNx, centerNy, speedMul) {
        for (let i = 0; i < count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const spd = (0.08 + Math.random() * 0.22) * (speedMul || 1);
          featherSparks.push({
            nx: centerNx + (Math.random() - 0.5) * 0.16,
            ny: centerNy + (Math.random() - 0.5) * 0.16,
            vx: Math.cos(angle) * spd,
            vy: Math.sin(angle) * spd - 0.05,
            life: 1.0,
            decay: 0.6 + Math.random() * 0.7,
            ch: Math.random() > 0.5 ? '1' : '0',
            size: 9 + ((Math.random() * 6) | 0)
          });
        }
        if (featherSparks.length > 90) featherSparks.splice(0, featherSparks.length - 90);
      }

      function triggerEagleScreech() {
        eagle.screechTimer = 1.35;
        eagle.ruffle = 1.0;
        eagle.targetPitch = -0.25;
        eagle.targetRoll = (Math.random() - 0.5) * 0.12;
        setActivityLabel('CYBER SCREECH & SONIC PULSE');
        triggerRipple(0.5, 0.48, 1.45);
        setTimeout(function() { triggerRipple(0.5, 0.48, 1.15); }, 180);
        spawnFeatherBurst(28, 0.5, 0.35, 1.3);
      }

      function triggerEagleScan() {
        eagle.scanBeamY = 0.0;
        eagle.ruffle = 0.85;
        eagle.blinkPhase = 0.01; // crisp blink before scan
        setActivityLabel('BIOMETRIC CODE SCAN');
        spawnFeatherBurst(18, 0.5, 0.28, 0.9);
      }

      // Fine Code Columns (forms the eagle out of falling '0' and '1' streams)
      let microCols = [];
      // Bokeh Foreground/Background Code Streams (larger glowing 0/1 drops like the edges of the image)
      let bokehDrops = [];

      function initColumns() {
        const colSpacing = 8; // 8px per column for dense binary eagle feathers
        const numCols = Math.ceil(width / colSpacing);
        microCols = [];
        for (let i = 0; i < numCols; i++) {
          microCols.push({
            x: i * colSpacing + 2,
            nx: (i * colSpacing + 2) / width,
            speed: 36 + (Math.sin(i * 17.3) * 0.5 + 0.5) * 52, // px per sec
            scrollY: Math.random() * 1000,
            waveOffset: Math.random() * Math.PI * 2,
            waveFreq: 0.035 + (i % 5) * 0.008,
            seed: (i * 73 + 19) & 255
          });
        }

        // Initialize 52 bokeh code rain streams (depth of field)
        bokehDrops = [];
        const numBokeh = 52;
        for (let i = 0; i < numBokeh; i++) {
          const isOuter = (i % 3 !== 0);
          let nx = Math.random();
          if (isOuter) {
            nx = (i % 2 === 0) ? (Math.random() * 0.28) : (0.72 + Math.random() * 0.28);
          }
          const depth = 0.4 + Math.random() * 0.9;
          const len = 7 + ((Math.random() * 12) | 0);
          const chars = [];
          for (let k = 0; k < len; k++) {
            chars.push(Math.random() > 0.48 ? '1' : '0');
          }
          bokehDrops.push({
            nx,
            y: Math.random() * height,
            speed: (65 + Math.random() * 115) * depth,
            size: Math.round(11 + depth * 9),
            len,
            chars,
            alpha: 0.22 + depth * 0.45,
            isOuter
          });
        }
      }

      function resizeCanvas() { if (!canvas.isConnected) return;
        const rect = canvas.parentElement.getBoundingClientRect();
        width = Math.max(320, Math.floor(rect.width));
        height = Math.max(420, Math.floor(rect.height));
        dpr = Math.min(window.devicePixelRatio || 1, 2);
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        initColumns();
      }

      window.addEventListener('resize', resizeCanvas);

      // Inverse mapping: from normalized eagle UV (nx, ny) to canvas pixel (px, py) including current head pose
      function eagleUVToCanvas(enx, eny, timeSec) {
        const targetAspect = 512 / 486;
        const canvasAspect = width / height;

        // Apply forward head pose transform around pivot (0.5, 0.36)
        let dx = enx - 0.5;
        let dy = eny - 0.36;

        // Breathing scale
        const breathScale = 1.0 + Math.sin(timeSec * 2.4) * 0.016 + eagle.screech * 0.035;
        dx *= breathScale;
        dy *= breathScale;

        // 2.5D Yaw shift & perspective foreshortening
        dx += eagle.yaw * 0.042 * (1.0 - Math.min(1.0, Math.abs(dy) * 1.4));
        dy += eagle.pitch * 0.028;

        // Roll rotation
        const cosR = Math.cos(eagle.roll);
        const sinR = Math.sin(eagle.roll);
        const rdx = dx * cosR - dy * sinR;
        const rdy = dx * sinR + dy * cosR;

        let nx = rdx + 0.5;
        let ny = rdy + 0.36;

        if (canvasAspect > targetAspect) {
          const scale = canvasAspect / targetAspect;
          nx = (nx - 0.5) / scale + 0.5;
        } else {
          const scale = targetAspect / canvasAspect;
          ny = (ny - 0.46) / scale + 0.46;
        }
        return { x: nx * width, y: ny * height };
      }

      // Map canvas (x, y) to animated normalized eagle space (nx, ny) with 2.5D head turn, tilt, breathing, feather ruffle & screech
      function toEagleUV(x, y, timeSec) {
        const targetAspect = 512 / 486;
        const canvasAspect = width / height;
        let nx = x / width;
        let ny = y / height;
        if (canvasAspect > targetAspect) {
          const scale = canvasAspect / targetAspect;
          nx = (nx - 0.5) * scale + 0.5;
        } else {
          const scale = targetAspect / canvasAspect;
          ny = (ny - 0.46) * scale + 0.46;
        }

        // Center pivot around eagle head (0.5, 0.36)
        let dx = nx - 0.5;
        let dy = ny - 0.36;

        // Inverse Roll (head tilt)
        const cosR = Math.cos(-eagle.roll);
        const sinR = Math.sin(-eagle.roll);
        const rdx = dx * cosR - dy * sinR;
        const rdy = dx * sinR + dy * cosR;
        dx = rdx;
        dy = rdy;

        // Breathing & Screech expansion
        const breath = 1.0 / (1.0 + Math.sin((timeSec || 0) * 2.4) * 0.016 + eagle.screech * 0.035);
        dx *= breath;
        dy *= breath;

        // 2.5D Perspective Head Turn (Yaw) & Nod (Pitch)
        const headWeight = Math.max(0.15, 1.0 - Math.max(0, dy) * 1.1);
        dx = dx - eagle.yaw * 0.042 * headWeight + dx * dx * eagle.yaw * 0.32;
        dy = dy - eagle.pitch * 0.028 * headWeight;

        let u = dx + 0.5;
        let v = dy + 0.36;

        // Anatomical Activity 1: Feather Ruffle & Crown Wind Gusts
        const distFromCenter = Math.abs(dx);
        if (distFromCenter > 0.14 && v > 0.06 && v < 0.85) {
          const ruffleAmp = (0.004 + eagle.ruffle * 0.018) * Math.min(1, (distFromCenter - 0.14) * 4);
          const wave = Math.sin(v * 28 - (timeSec || 0) * 14 + distFromCenter * 12);
          u -= Math.sign(dx) * wave * ruffleAmp;
        }

        // Anatomical Activity 2: Fierce Brow Furrow during Screech or Login Watch
        if (v > 0.21 && v < 0.31 && distFromCenter < 0.18) {
          const furrow = (eagle.screech * 0.014 + (eagle.watchingForm ? 0.008 : 0)) * (1.0 - distFromCenter / 0.18);
          v -= furrow;
        }

        // Anatomical Activity 3: Beak Opening / Lower Jaw Drop during Screech
        if (eagle.screech > 0.01 && distFromCenter < 0.095 && v > 0.36 && v < 0.66) {
          const jawFactor = (1.0 - distFromCenter / 0.095) * Math.sin(((v - 0.36) / 0.30) * Math.PI);
          v -= eagle.screech * 0.048 * jawFactor;
        }

        return { nx: u, ny: v };
      }

      // Update Eagle Autonomous & Reactive Activity State Machine
      function updateEagleActivity(dt, timeSec) {
        // 1. Update Screech timer
        if (eagle.screechTimer > 0) {
          eagle.screechTimer -= dt;
          eagle.screech = Math.min(1.0, eagle.screech + dt * 7.5);
        } else {
          eagle.screech = Math.max(0.0, eagle.screech - dt * 4.5);
        }

        // 2. Decay feather ruffle
        eagle.ruffle = Math.max(0.0, eagle.ruffle - dt * 1.1);

        // 3. Update Holographic Scan Beam
        if (eagle.scanBeamY >= 0) {
          eagle.scanBeamY += dt * 0.65;
          if (eagle.scanBeamY > 1.15) eagle.scanBeamY = -1;
        }

        // 4. Blinking Eyelid State Machine
        if (eagle.blinkPhase > 0) {
          eagle.blinkPhase += dt * 7.5;
          if (eagle.blinkPhase < 1.0) {
            eagle.blink = eagle.blinkPhase; // closing
          } else if (eagle.blinkPhase < 2.0) {
            eagle.blink = 2.0 - eagle.blinkPhase; // opening
          } else {
            eagle.blink = 0;
            eagle.blinkPhase = 0;
          }
        } else {
          eagle.nextBlinkIn -= dt;
          if (eagle.nextBlinkIn <= 0) {
            eagle.blinkPhase = 0.01;
            // Occasionally double-blink like a real bird of prey
            eagle.nextBlinkIn = Math.random() < 0.28 ? 0.35 : (2.4 + Math.random() * 3.2);
          }
        }

        // 5. Determine Target Head Pose (Pointer vs Watching Login Form vs Autonomous Raptor Patrol)
        if (pointer.active) {
          eagle.targetYaw = (pointer.x - 0.5) * 1.35;
          eagle.targetPitch = (pointer.y - 0.42) * 1.1;
          eagle.targetRoll = (pointer.x - 0.5) * -0.14;
          if (eagle.screechTimer <= 0 && eagle.scanBeamY < 0) {
            setActivityLabel('TRACKING CURSOR TARGET');
          }
        } else if (eagle.watchingForm) {
          // Look toward the Login Form on the right panel!
          eagle.targetYaw = 0.72 + Math.sin(timeSec * 2.0) * 0.08;
          eagle.targetPitch = 0.06;
          eagle.targetRoll = -0.07;
        } else {
          // Autonomous Raptor Patrol Cycle (looks left, right, tilts head, scans, ruffles feathers)
          eagle.nextActionIn -= dt;
          if (eagle.nextActionIn <= 0) {
            const rollChoice = Math.random();
            if (rollChoice < 0.28) {
              // Look sharply left
              eagle.targetYaw = -0.65 - Math.random() * 0.25;
              eagle.targetPitch = -0.1 + Math.random() * 0.2;
              eagle.targetRoll = 0.08;
              eagle.blinkPhase = 0.01;
              setActivityLabel('SCANNING SECTOR WEST');
              eagle.nextActionIn = 2.2 + Math.random() * 1.5;
            } else if (rollChoice < 0.56) {
              // Look sharply right toward login form
              eagle.targetYaw = 0.65 + Math.random() * 0.25;
              eagle.targetPitch = -0.05 + Math.random() * 0.2;
              eagle.targetRoll = -0.08;
              eagle.blinkPhase = 0.01;
              setActivityLabel('GUARDING LOGIN GATEWAY');
              eagle.nextActionIn = 2.2 + Math.random() * 1.5;
            } else if (rollChoice < 0.76) {
              // Lock center & ruffle crown feathers
              eagle.targetYaw = (Math.random() - 0.5) * 0.18;
              eagle.targetPitch = -0.15;
              eagle.targetRoll = (Math.random() - 0.5) * 0.14;
              eagle.ruffle = 0.95;
              spawnFeatherBurst(16, 0.5, 0.25, 0.85);
              setActivityLabel('PLUMAGE CODE REFRESH');
              eagle.nextActionIn = 2.0 + Math.random() * 1.4;
            } else if (rollChoice < 0.90) {
              // Biometric scan wave
              eagle.targetYaw = 0;
              eagle.targetPitch = 0;
              eagle.targetRoll = 0;
              triggerEagleScan();
              eagle.nextActionIn = 2.6;
            } else {
              // Autonomous brief cyber screech
              eagle.targetYaw = 0;
              triggerEagleScreech();
              eagle.nextActionIn = 3.0;
            }
          }
        }

        // Smooth spring-like interpolation for natural raptor head snapping
        const snapSpeed = Math.min(1.0, dt * 6.5);
        eagle.yaw += (eagle.targetYaw - eagle.yaw) * snapSpeed;
        eagle.pitch += (eagle.targetPitch - eagle.pitch) * snapSpeed;
        eagle.roll += (eagle.targetRoll - eagle.roll) * snapSpeed;

        // Update floating binary feather sparks
        for (let i = featherSparks.length - 1; i >= 0; i--) {
          const sp = featherSparks[i];
          sp.nx += sp.vx * dt;
          sp.ny += sp.vy * dt;
          sp.life -= sp.decay * dt;
          if (sp.life <= 0) featherSparks.splice(i, 1);
        }
      }

      // Check if a normalized eagle coordinate (nx, ny) is covered by the blinking eyelid or open screech mouth
      function getAnatomicalModifier(nx, ny) {
        // Left eye: (0.381, 0.312), Right eye: (0.619, 0.312)
        const lx = nx - 0.381;
        const rx = nx - 0.619;
        const ey = ny - 0.312;
        const rEye = 0.046;
        const inLeftEye = (lx * lx + ey * ey) < (rEye * rEye);
        const inRightEye = (rx * rx + ey * ey) < (rEye * rEye);

        if ((inLeftEye || inRightEye) && eagle.blink > 0.02) {
          // Eyelid sweeps shut toward ey = 0
          const openSlit = (1.0 - eagle.blink) * rEye;
          if (Math.abs(ey) > openSlit) {
            return { mult: 0.08, add: 0 }; // Dark closed eyelid
          } else if (Math.abs(ey) > openSlit * 0.7) {
            return { mult: 1.3, add: 0.45 }; // Glowing eyelid rim
          }
        }

        // Inner beak cyber-energy flare when screeching
        if (eagle.screech > 0.05) {
          const bx = (nx - 0.5) / 0.045;
          const by = (ny - 0.49) / (0.045 * eagle.screech + 0.01);
          if (bx * bx + by * by < 1.0) {
            return { mult: 1.2, add: eagle.screech * 0.65 * (1.0 - (bx * bx + by * by)) };
          }
        }

        return { mult: 1.0, add: 0 };
      }

      // Update offscreen volumetric code-stream field
      function updateVolumetricField(timeSec) {
        let idx = 0;
        for (let py = 0; py < VOL_H; py++) {
          const yCanvas = (py / VOL_H) * height;
          for (let px = 0; px < VOL_W; px++) {
            const xCanvas = (px / VOL_W) * width;
            const uv = toEagleUV(xCanvas, yCanvas, timeSec);
            const mod = getAnatomicalModifier(uv.nx, uv.ny);
            const eVal = sampleEagle(uv.nx, uv.ny) * mod.mult + mod.add;

            // Vertical code-drop wave modulation along columns
            const colWave = 0.72 + 0.28 * Math.sin(py * 0.42 - timeSec * 5.8 + Math.sin(px * 1.7) * 3.0);
            const scanline = (py & 1) === 0 ? 1.05 : 0.82;

            // Ripple shockwave + Scan Beam boost
            let rippleBoost = 0;
            for (let r = 0; r < ripples.length; r++) {
              const rp = ripples[r];
              const dx = uv.nx - rp.nx;
              const dy = uv.ny - rp.ny;
              const dist = Math.sqrt(dx * dx + dy * dy);
              const ring = Math.abs(dist - rp.radius);
              if (ring < 0.045) {
                rippleBoost += (1.0 - ring / 0.045) * rp.strength * 0.6;
              }
            }
            if (eagle.scanBeamY >= 0 && Math.abs(uv.ny - eagle.scanBeamY) < 0.035 && eVal > 0.12) {
              rippleBoost += (1.0 - Math.abs(uv.ny - eagle.scanBeamY) / 0.035) * 0.55;
            }

            const v = Math.min(1.0, eVal * colWave * scanline + rippleBoost);

            let R, G, B;
            if (v < 0.12) {
              const t = v / 0.12;
              R = 2 + t * 3;
              G = 8 + t * 18;
              B = 20 + t * 38;
            } else if (v < 0.45) {
              const t = (v - 0.12) / 0.33;
              R = 5 + t * 8;
              G = 26 + t * 115;
              B = 58 + t * 145;
            } else if (v < 0.78) {
              const t = (v - 0.45) / 0.33;
              R = 13 + t * 75;
              G = 141 + t * 92;
              B = 203 + t * 50;
            } else {
              const t = (v - 0.78) / 0.22;
              R = 88 + t * 167;
              G = 233 + t * 22;
              B = 253 + t * 2;
            }

            volPixels[idx++] = R | 0;
            volPixels[idx++] = G | 0;
            volPixels[idx++] = B | 0;
            volPixels[idx++] = 255;
          }
        }
        offCtx.putImageData(volImgData, 0, 0);
      }

      // Main 60 FPS Animation Loop
      let lastTime = performance.now();
      let frameCount = 0;
      let fpsTimer = performance.now();
      const fpsEl = document.getElementById('fpsCounter');

      function animate(now) { if (!canvas.isConnected) return;
        const dt = Math.min(0.05, (now - lastTime) / 1000);
        lastTime = now;
        const timeSec = now * 0.001;

        frameCount++;
        if (now - fpsTimer > 600) {
          const fps = Math.round((frameCount * 1000) / (now - fpsTimer));
          if (fpsEl) fpsEl.textContent = fps + ' FPS';
          frameCount = 0;
          fpsTimer = now;
        }

        // Update Living Eagle Activity State
        updateEagleActivity(dt, timeSec);

        // Update ripples
        for (let i = ripples.length - 1; i >= 0; i--) {
          ripples[i].radius += dt * 0.48;
          ripples[i].strength *= 0.96;
          if (ripples[i].radius > ripples[i].maxRadius || ripples[i].strength < 0.04) {
            ripples.splice(i, 1);
          }
        }

        // 1. Background / Volumetric Layer
        if (renderMode === 'hybrid') {
          updateVolumetricField(timeSec);
          ctx.imageSmoothingEnabled = true;
          ctx.drawImage(offCanvas, 0, 0, width, height);
          ctx.fillStyle = 'rgba(2, 8, 20, 0.36)';
          ctx.fillRect(0, 0, width, height);
        } else {
          ctx.fillStyle = '#030917';
          ctx.fillRect(0, 0, width, height);
        }

        // 2. Layer 2: High-Density Falling Binary Character Matrix (Sculpts the Moving Eagle out of 0 and 1 glyphs)
        const rowStep = 9;
        const numRows = Math.ceil(height / rowStep) + 1;
        ctx.font = 'bold 8.5px "JetBrains Mono", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        const speedBoost = 1.0 + eagle.screech * 0.8 + eagle.ruffle * 0.5;

        for (let c = 0; c < microCols.length; c++) {
          const col = microCols[c];
          col.scrollY = (col.scrollY + col.speed * speedBoost * dt) % (rowStep * 1000);
          const subShift = col.scrollY % rowStep;
          const baseRowShift = (col.scrollY / rowStep) | 0;

          for (let r = -1; r < numRows; r++) {
            const y = r * rowStep + subShift;
            if (y < 0 || y > height) continue;

            const uv = toEagleUV(col.x, y, timeSec);
            const mod = getAnatomicalModifier(uv.nx, uv.ny);
            const eVal = sampleEagle(uv.nx, uv.ny) * mod.mult + mod.add;
            const edgeVal = sampleEagleEdge(uv.nx, uv.ny) * mod.mult;

            const logicalRow = r - baseRowShift;
            const rainWave = Math.sin(logicalRow * 0.22 + col.waveOffset);
            const isRainHead = rainWave > 0.92;

            let rippleHit = 0;
            if (pointer.active) {
              const dx = (col.x / width) - pointer.x;
              const dy = (y / height) - pointer.y;
              const d2 = dx * dx + dy * dy;
              if (d2 < 0.012) {
                rippleHit = (1.0 - d2 / 0.012) * 0.55;
              }
            }
            for (let k = 0; k < ripples.length; k++) {
              const rp = ripples[k];
              const dx = uv.nx - rp.nx;
              const dy = uv.ny - rp.ny;
              const dist = Math.sqrt(dx * dx + dy * dy);
              if (Math.abs(dist - rp.radius) < 0.035) {
                rippleHit = Math.max(rippleHit, rp.strength * 0.85);
              }
            }
            if (eagle.scanBeamY >= 0 && Math.abs(uv.ny - eagle.scanBeamY) < 0.028 && eVal > 0.1) {
              rippleHit = Math.max(rippleHit, 0.85);
            }

            const totalEnergy = Math.min(1.0, eVal * 0.88 + edgeVal * 0.35 + (rainWave > 0.4 ? (rainWave - 0.4) * 0.25 : 0) + rippleHit);

            if (totalEnergy < 0.13 && !isRainHead) continue;

            const bitHash = ((logicalRow * 31 + col.seed + ((timeSec * 3.5) | 0)) & 7);
            const ch = (bitHash === 0 || bitHash === 3 || bitHash === 5 || bitHash === 6) ? '1' : '0';

            if (totalEnergy > 0.76 || (isRainHead && totalEnergy > 0.35)) {
              ctx.fillStyle = '#e0faff';
            } else if (totalEnergy > 0.52) {
              ctx.fillStyle = '#38e8ff';
            } else if (totalEnergy > 0.30) {
              ctx.fillStyle = '#0ea5e9';
            } else {
              ctx.fillStyle = 'rgba(2, 132, 199, 0.48)';
            }

            ctx.fillText(ch, col.x, y);
          }
        }

        // 3. Layer 3: Living Eagle Eyes (Blinking, Gaze-Tracking Pupils, Rotating Cyber HUD Rings & Screech Core)
        const eyePulse = (0.85 + 0.15 * Math.sin(timeSec * 3.8)) * (1.0 - eagle.blink * 0.85);
        const eyes = [
          { nx: 0.381, ny: 0.312 },
          { nx: 0.619, ny: 0.312 }
        ];
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';

        for (let i = 0; i < eyes.length; i++) {
          const pos = eagleUVToCanvas(eyes[i].nx, eyes[i].ny, timeSec);
          // Gaze offset shifts pupils & iris ring toward target direction
          const gazeX = pos.x + eagle.yaw * 7;
          const gazeY = pos.y + eagle.pitch * 5;
          const rGlow = Math.min(width, height) * 0.058 * (1.0 + eagle.screech * 0.3);

          // Radial eye bloom (squashes vertically during blink!)
          ctx.save();
          ctx.translate(gazeX, gazeY);
          ctx.scale(1.0, Math.max(0.08, 1.0 - eagle.blink * 0.92));

          const grad = ctx.createRadialGradient(0, 0, rGlow * 0.1, 0, 0, rGlow);
          grad.addColorStop(0, 'rgba(210, 252, 255, ' + (0.58 * eyePulse).toFixed(2) + ')');
          grad.addColorStop(0.45, 'rgba(0, 225, 255, ' + (0.34 * eyePulse).toFixed(2) + ')');
          grad.addColorStop(1, 'rgba(0, 140, 255, 0)');
          ctx.fillStyle = grad;
          ctx.beginPath();
          ctx.arc(0, 0, rGlow, 0, Math.PI * 2);
          ctx.fill();

          // Rotating Cybernetic Iris Reticle Ring
          if (eagle.blink < 0.65) {
            const ringR = rGlow * 0.36;
            ctx.strokeStyle = 'rgba(165, 243, 252, 0.55)';
            ctx.lineWidth = 1.4;
            ctx.beginPath();
            const rot = timeSec * (i === 0 ? 1.8 : -1.8);
            ctx.arc(0, 0, ringR, rot, rot + Math.PI * 1.15);
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(0, 0, ringR * 0.72, -rot * 1.3, -rot * 1.3 + Math.PI * 0.8);
            ctx.stroke();
          }
          ctx.restore();
        }

        // 4. Floating Feather Code Sparks (emitted during screech, ruffle & scan)
        if (featherSparks.length > 0) {
          for (let i = 0; i < featherSparks.length; i++) {
            const sp = featherSparks[i];
            const cPos = eagleUVToCanvas(sp.nx, sp.ny, timeSec);
            ctx.font = 'bold ' + sp.size + 'px "JetBrains Mono", monospace';
            ctx.fillStyle = 'rgba(125, 242, 255, ' + Math.max(0, sp.life * 0.9).toFixed(2) + ')';
            ctx.fillText(sp.ch, cPos.x, cPos.y);
          }
        }

        // 5. Layer 5: Foreground & Framing Depth-of-Field Bokeh Binary Code Drops (0 / 1)
        for (let i = 0; i < bokehDrops.length; i++) {
          const drop = bokehDrops[i];
          drop.y += drop.speed * (1.0 + eagle.screech * 0.45) * dt;
          if (drop.y - drop.len * drop.size > height) {
            drop.y = -drop.size * 2;
          }
          const x = drop.nx * width;
          ctx.font = 'bold ' + drop.size + 'px "JetBrains Mono", monospace';

          for (let k = 0; k < drop.len; k++) {
            const cy = drop.y - k * (drop.size * 1.05);
            if (cy < -20 || cy > height + 20) continue;
            const fade = 1.0 - (k / drop.len);
            if (Math.random() < 0.025) {
              drop.chars[k] = drop.chars[k] === '1' ? '0' : '1';
            }
            if (k === 0) {
              ctx.fillStyle = 'rgba(205, 250, 255, ' + (drop.alpha * 0.95).toFixed(2) + ')';
            } else {
              ctx.fillStyle = 'rgba(0, 195, 255, ' + (drop.alpha * fade * 0.65).toFixed(2) + ')';
            }
            ctx.fillText(drop.chars[k], x, cy);
          }
        }
        ctx.restore();

        requestAnimationFrame(animate);
      }

      // Pointer interactions on the Code-Drop Eagle Canvas
      canvas.addEventListener('mousemove', function(e) {
        const rect = canvas.getBoundingClientRect();
        pointer.x = (e.clientX - rect.left) / rect.width;
        pointer.y = (e.clientY - rect.top) / rect.height;
        pointer.active = true;
      });
      canvas.addEventListener('mouseleave', function() {
        pointer.active = false;
      });
      canvas.addEventListener('click', function(e) {
        const rect = canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const uv = toEagleUV(x, y, performance.now() * 0.001);
        triggerRipple(uv.nx, uv.ny, 1.35);
        triggerEagleScreech();
      });

      // Mode & Activity switch buttons
      const modeHybridBtn = document.getElementById('modeHybridBtn');
      const modePureAsciiBtn = document.getElementById('modePureAsciiBtn');
      const pulseBoostBtn = document.getElementById('pulseBoostBtn');
      const ruffleBtn = document.getElementById('ruffleBtn');

      function updateModeButtons() {
        if (renderMode === 'hybrid') {
          modeHybridBtn.className = 'px-2.5 py-1 rounded-full font-medium transition bg-sky-400/25 text-sky-200 border border-sky-400/40';
          modePureAsciiBtn.className = 'px-2.5 py-1 rounded-full font-medium transition text-slate-300 hover:text-white';
        } else {
          modePureAsciiBtn.className = 'px-2.5 py-1 rounded-full font-medium transition bg-sky-400/25 text-sky-200 border border-sky-400/40';
          modeHybridBtn.className = 'px-2.5 py-1 rounded-full font-medium transition text-slate-300 hover:text-white';
        }
      }

      modeHybridBtn.addEventListener('click', function() {
        renderMode = 'hybrid';
        updateModeButtons();
        triggerRipple(0.5, 0.38, 1.0);
      });

      modePureAsciiBtn.addEventListener('click', function() {
        renderMode = 'pure';
        updateModeButtons();
        triggerRipple(0.5, 0.38, 1.0);
      });

      pulseBoostBtn.addEventListener('click', function() {
        triggerEagleScreech();
      });

      if (ruffleBtn) {
        ruffleBtn.addEventListener('click', function() {
          triggerEagleScan();
        });
      }
      // Keep the original eagle reactions to login-field focus and typing.
      const emailInput = document.getElementById('emailInput');
      const passwordInput = document.getElementById('passwordInput');
      if (emailInput && passwordInput) {
        emailInput.addEventListener('focus', function() {
          eagle.watchingForm = true;
          setActivityLabel('WATCHING EMAIL INPUT');
        });
        emailInput.addEventListener('blur', function() { eagle.watchingForm = false; });
        emailInput.addEventListener('input', function() {
          eagle.watchingForm = true;
          eagle.targetPitch = 0.04 + (emailInput.value.length % 5) * 0.015;
          spawnFeatherBurst(3, 0.62, 0.31, 0.6);
        });
        passwordInput.addEventListener('focus', function() {
          eagle.watchingForm = true;
          eagle.blinkPhase = 0.01;
          setActivityLabel('VERIFYING SECURITY CREDENTIALS');
        });
        passwordInput.addEventListener('blur', function() { eagle.watchingForm = false; });
        passwordInput.addEventListener('input', function() {
          eagle.watchingForm = true;
          eagle.ruffle = 0.45;
          triggerRipple(0.619, 0.312, 0.45);
        });
      }
      // Initialize after React has mounted the login view.
      resizeCanvas();
      triggerRipple(0.5, 0.35, 1.15);
      requestAnimationFrame(animate);
    })();
